// Package render turns config.yaml into the git-facing files gids owns. It is
// pure: given the same inputs it always produces the same bytes, which is what
// makes "self-heal = compare and rewrite" safe (SPEC §7.2).
package render

import (
	"fmt"
	"path/filepath"
	"slices"
	"strings"

	"gids/internal/config"
)

// File is one generated file, relative to the gids directory.
type File struct {
	Rel     string // '/'-separated path under the gids dir
	Content string
	Exec    bool // hooks are executable
}

// Hooks gids installs. commit-msg (not prepare-commit-msg) adds co-authors:
// see PROGRESS.md decision D1.
var Hooks = []string{"pre-commit", "commit-msg", "post-commit"}

// Managed reports whether rel (a '/'-separated path inside the gids
// directory) is a name gids generates: the root gitconfig, a profile's
// gitconfig, or one of Hooks. Only these are ever deleted as strays, so a
// file someone else put there (a README, Finder's .DS_Store, a dotfiles
// manager's marker) is left alone.
func Managed(rel string) bool {
	dir, name, ok := strings.Cut(rel, "/")
	switch {
	case !ok:
		return rel == "gitconfig"
	case strings.Contains(name, "/"):
		return false
	case dir == "profiles":
		p := strings.TrimSuffix(name, ".gitconfig")
		return p != name && config.ValidateProfileName(p) == nil
	case dir == "hooks":
		return slices.Contains(Hooks, name)
	}
	return false
}

const header = "# Generated by gids from config.yaml. Don't edit: changes are overwritten.\n"

// Input is everything rendering depends on besides config.yaml.
type Input struct {
	Home          string // for expanding ~ in SSH key paths
	Exe           string // absolute path of the gids binary, baked into hooks
	PrevHooksPath string // the hooks dir that would run without gids ("" = repo's own)
}

// Render returns every generated file, in a stable order.
func Render(cfg *config.Config, in Input) []File {
	var files []File
	files = append(files, File{Rel: "gitconfig", Content: renderRules(cfg, in.Home)})
	for _, p := range cfg.Profiles {
		files = append(files, File{Rel: "profiles/" + p.Name + ".gitconfig", Content: renderProfile(p, in.Home)})
	}
	for _, h := range Hooks {
		files = append(files, File{Rel: "hooks/" + h, Content: renderHook(h, in.Exe, in.PrevHooksPath), Exec: true})
	}
	return files
}

func renderRules(cfg *config.Config, home string) string {
	var b strings.Builder
	b.WriteString(header)
	for _, dir := range config.SortedRules(cfg.Rules, home) {
		// Rule keys can't contain '"' or '\' (validated), so the subsection
		// needs no escaping.
		fmt.Fprintf(&b, "[includeIf \"gitdir:%s\"]\n\tpath = %s\n", dir, Quote("profiles/"+cfg.Rules[dir]+".gitconfig"))
	}
	return b.String()
}

func renderProfile(p config.Profile, home string) string {
	var b strings.Builder
	b.WriteString(header)
	fmt.Fprintf(&b, "[user]\n\tname = %s\n\temail = %s\n", Quote(p.GitName), Quote(p.GitEmail))
	if p.SigningKey != "" {
		key := expandHome(p.SigningKey, home)
		fmt.Fprintf(&b, "\tsigningKey = %s\n", Quote(key))
		if IsSSHSigningKey(p.SigningKey) {
			b.WriteString("[gpg]\n\tformat = ssh\n")
		}
	}
	if p.SSHKey != "" {
		fmt.Fprintf(&b, "[core]\n\tsshCommand = %s\n", Quote(SSHCommand(expandHome(p.SSHKey, home))))
	}
	if p.Username != "" {
		fmt.Fprintf(&b, "[credential]\n\tusername = %s\n", Quote(p.Username))
	}
	fmt.Fprintf(&b, "[gids]\n\tprofile = %s\n", Quote(p.Name))
	return b.String()
}

// IsSSHSigningKey reports whether a signing key refers to an SSH key (a path
// or a literal "key::…") rather than a GPG key id.
func IsSSHSigningKey(k string) bool {
	return strings.HasPrefix(k, "~/") || strings.HasPrefix(k, "/") || strings.HasPrefix(k, "./") ||
		strings.HasPrefix(k, "key::") || strings.HasSuffix(k, ".pub") || filepath.IsAbs(k)
}

// SSHCommand builds core.sshCommand for a key. git runs it through sh -c, so
// the path is single-quoted. IdentitiesOnly stops ssh-agent from offering a
// different account's key first (BUGS.md B7).
func SSHCommand(keyPath string) string {
	return "ssh -i " + ShellQuote(keyPath) + " -o IdentitiesOnly=yes"
}

// ShellQuote single-quotes s for POSIX sh.
func ShellQuote(s string) string {
	return "'" + strings.ReplaceAll(s, "'", `'\''`) + "'"
}

// Quote renders s as a git-config value: always double-quoted, with '\', '"'
// and tab escaped. Callers guarantee there are no newlines (validated), so
// the result always reads back as exactly s.
func Quote(s string) string {
	r := strings.NewReplacer(`\`, `\\`, `"`, `\"`, "\t", `\t`)
	return `"` + r.Replace(s) + `"`
}

func expandHome(p, home string) string {
	if strings.HasPrefix(p, "~/") {
		return filepath.ToSlash(filepath.Join(home, p[2:]))
	}
	return p
}

// renderHook is the shim git runs. It calls gids, then chains to the hook that
// would have run without gids (core.hooksPath replaces .git/hooks globally,
// BUGS.md B6). If the gids binary is gone, it warns and still chains, so a
// broken install never blocks commits or swallows the repo's own hooks.
func renderHook(name, exe, prev string) string {
	var b strings.Builder
	b.WriteString("#!/bin/sh\n" + header)
	fmt.Fprintf(&b, "gids=%s\n", ShellQuote(filepath.ToSlash(exe)))
	fmt.Fprintf(&b, "if [ -x \"$gids\" ]; then\n\t\"$gids\" hook-exec %s \"$@\" || exit $?\nelse\n\techo \"gids: $gids not found; skipping gids %s hook\" >&2\nfi\n", name, name)
	if prev != "" {
		fmt.Fprintf(&b, "h=%s/%s\n", ShellQuote(filepath.ToSlash(prev)), name)
	} else {
		fmt.Fprintf(&b, "d=$(git rev-parse --git-common-dir) && h=\"$d/hooks/%s\" || h=\n", name)
	}
	// Never chain to this very file (a hooks dir symlinked to gids' own would
	// otherwise exec itself forever and hang the commit).
	b.WriteString("if [ -n \"$h\" ] && [ -x \"$h\" ] && ! [ \"$h\" -ef \"$0\" ]; then exec \"$h\" \"$@\"; fi\nexit 0\n")
	return b.String()
}
